using System.Collections.Generic;

public class LRUCache {
    private Dictionary<int, LinkedListNode<(int key, int value)>> dict;
    private LinkedList<(int key, int value)> list;
    private int capacity;
    public LRUCache(int capacity) { this.capacity = capacity; dict = new(); list = new(); }
    public int Get(int key) {
        if (!dict.ContainsKey(key)) return -1;
        var node = dict[key];
        list.Remove(node);
        list.AddFirst(node);
        return node.Value.value;
    }
    public void Put(int key, int value) {
        if (dict.ContainsKey(key)) list.Remove(dict[key]);
        var node = list.AddFirst((key, value));
        dict[key] = node;
        if (dict.Count > capacity) {
            var last = list.Last;
            dict.Remove(last.Value.key);
            list.RemoveLast();
        }
    }
}

