using System.Collections.Generic;

public static List<int> MergeKLists(List<List<int>> lists) {
    var heap = new SortedSet<(int val, int listIdx, int elemIdx)>(Comparer<(int, int, int)>.Create((a,b) => a.Item1.CompareTo(b.Item1)));
    for (int i = 0; i < lists.Count; i++) {
        if (lists[i].Count > 0) heap.Add((lists[i][0], i, 0));
    }
    var result = new List<int>();
    while (heap.Count > 0) {
        var (val, i, idx) = heap.Min;
        heap.Remove(heap.Min);
        result.Add(val);
        if (idx + 1 < lists[i].Count) heap.Add((lists[i][idx+1], i, idx+1));
    }
    return result;
}

