import java.util.*;

public static List<Integer> mergeKLists(List<List<Integer>> lists) {
    PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
    for (int i = 0; i < lists.size(); i++) {
        if (!lists.get(i).isEmpty()) heap.offer(new int[]{lists.get(i).get(0), i, 0});
    }
    List<Integer> result = new ArrayList<>();
    while (!heap.isEmpty()) {
        int[] top = heap.poll();
        int val = top[0], listIdx = top[1], elemIdx = top[2];
        result.add(val);
        if (elemIdx + 1 < lists.get(listIdx).size()) {
            heap.offer(new int[]{lists.get(listIdx).get(elemIdx+1), listIdx, elemIdx+1});
        }
    }
    return result;
}

