class MinHeap {
    constructor() { this.heap = []; }
    push(node) { this.heap.push(node); this.bubbleUp(this.heap.length-1); }
    pop() { const min = this.heap[0]; const last = this.heap.pop(); if (this.heap.length) { this.heap[0] = last; this.sinkDown(0); } return min; }
    bubbleUp(i) { while (i>0) { const p = (i-1)>>1; if (this.heap[p].val <= this.heap[i].val) break; [this.heap[p], this.heap[i]] = [this.heap[i], this.heap[p]]; i=p; } }
    sinkDown(i) { const n=this.heap.length; while(true) { let left=2*i+1, right=2*i+2, swap=null; if (left<n && this.heap[left].val < this.heap[i].val) swap=left; if (right<n && this.heap[right].val < (swap===null?this.heap[i].val:this.heap[left].val)) swap=right; if (swap===null) break; [this.heap[i], this.heap[swap]] = [this.heap[swap], this.heap[i]]; i=swap; } }
    size() { return this.heap.length; }
}

function mergeKLists(lists) {
    const heap = new MinHeap();
    for (let i = 0; i < lists.length; i++) {
        if (lists[i].length) heap.push({ val: lists[i][0], listIdx: i, elemIdx: 0 });
    }
    const result = [];
    while (heap.size()) {
        const { val, listIdx, elemIdx } = heap.pop();
        result.push(val);
        if (elemIdx + 1 < lists[listIdx].length) {
            heap.push({ val: lists[listIdx][elemIdx+1], listIdx, elemIdx: elemIdx+1 });
        }
    }
    return result;
}

