def copy_random_list(head):
    if not head: return None
    node_map = {}
    curr = head
    while curr:
        node_map[curr] = {'val': curr['val'], 'next': None, 'random': None}
        curr = curr['next']
    curr = head
    while curr:
        copy = node_map[curr]
        copy['next'] = node_map.get(curr['next'])
        copy['random'] = node_map.get(curr['random'])
        curr = curr['next']
    return node_map[head]

