using System.Collections.Generic;

public class TreeNode { public int val; public TreeNode left; public TreeNode right; public TreeNode(int x) { val = x; } }

public static string Serialize(TreeNode root) {
    if (root == null) return "[]";
    var queue = new Queue<TreeNode>();
    queue.Enqueue(root);
    var result = new List<string>();
    while (queue.Count > 0) {
        var node = queue.Dequeue();
        if (node != null) {
            result.Add(node.val.ToString());
            queue.Enqueue(node.left);
            queue.Enqueue(node.right);
        } else {
            result.Add("null");
        }
    }
    while (result.Count > 0 && result[^1] == "null") result.RemoveAt(result.Count-1);
    return "[" + string.Join(",", result) + "]";
}

public static TreeNode Deserialize(string data) {
    if (data == "[]") return null;
    var vals = data.Substring(1, data.Length-2).Split(',');
    var root = new TreeNode(int.Parse(vals[0]));
    var queue = new Queue<TreeNode>();
    queue.Enqueue(root);
    int i = 1;
    while (queue.Count > 0 && i < vals.Length) {
        var node = queue.Dequeue();
        if (i < vals.Length && vals[i] != "null") {
            node.left = new TreeNode(int.Parse(vals[i]));
            queue.Enqueue(node.left);
        }
        i++;
        if (i < vals.Length && vals[i] != "null") {
            node.right = new TreeNode(int.Parse(vals[i]));
            queue.Enqueue(node.right);
        }
        i++;
    }
    return root;
}

