public static double[] MinMaxNormalize(double[] data) {
    if (data.Length == 0) return new double[0];
    double min = data.Min();
    double max = data.Max();
    if (max == min) return Enumerable.Repeat(0.0, data.Length).ToArray();
    return data.Select(x => (x - min) / (max - min)).ToArray();
}

