public static double[] minMaxNormalize(double[] data) {
    if (data.length == 0) return new double[0];
    double min = Double.MAX_VALUE, max = Double.MIN_VALUE;
    for (double v : data) { min = Math.min(min, v); max = Math.max(max, v); }
    if (max == min) return new double[data.length];
    double[] result = new double[data.length];
    for (int i = 0; i < data.length; i++) {
        result[i] = (data[i] - min) / (max - min);
    }
    return result;
}

