public static (List<int> X_train, List<int> X_test, List<string> y_train, List<string> y_test) TrainTestSplit(List<int> X, List<string> y, double testRatio, int seed = 42) {
    var rnd = new Random(seed);
    var indices = Enumerable.Range(0, X.Count).ToList();
    indices = indices.OrderBy(i => rnd.Next()).ToList();
    int splitIdx = (int)(X.Count * (1 - testRatio));
    var trainIdx = indices.Take(splitIdx).ToList();
    var testIdx = indices.Skip(splitIdx).ToList();
    return (trainIdx.Select(i => X[i]).ToList(), testIdx.Select(i => X[i]).ToList(),
            trainIdx.Select(i => y[i]).ToList(), testIdx.Select(i => y[i]).ToList());
}

