import java.util.*;
import java.util.stream.Collectors;

public class Splitter {
    public static List<List<Object>> trainTestSplit(List<Integer> X, List<String> y, double testRatio, int seed) {
        Random rand = new Random(seed);
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < X.size(); i++) indices.add(i);
        Collections.shuffle(indices, rand);
        int splitIdx = (int)(X.size() * (1 - testRatio));
        List<Integer> trainIdx = indices.subList(0, splitIdx);
        List<Integer> testIdx = indices.subList(splitIdx, indices.size());
        return Arrays.asList(
            trainIdx.stream().map(X::get).collect(Collectors.toList()),
            testIdx.stream().map(X::get).collect(Collectors.toList()),
            trainIdx.stream().map(y::get).collect(Collectors.toList()),
            testIdx.stream().map(y::get).collect(Collectors.toList())
        );
    }
}

