function trainTestSplit(X, y, testRatio, seed = 42) {
    function seededRandom(seed) {
        let m = 0x80000000;
        let a = 1103515245;
        let c = 12345;
        return function() {
            seed = (a * seed + c) % m;
            return seed / m;
        };
    }
    const rng = seededRandom(seed);
    let indices = X.map((_, i) => i);
    for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(rng() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
    }
    const splitIdx = Math.floor(X.length * (1 - testRatio));
    const trainIdx = indices.slice(0, splitIdx);
    const testIdx = indices.slice(splitIdx);
    const X_train = trainIdx.map(i => X[i]);
    const X_test = testIdx.map(i => X[i]);
    const y_train = trainIdx.map(i => y[i]);
    const y_test = testIdx.map(i => y[i]);
    return { X_train, X_test, y_train, y_test };
}

