import java.util.*;

public static List<List<Integer>> oneHotEncode(List<String> labels) {
    Set<String> unique = new TreeSet<>(labels);
    List<String> categories = new ArrayList<>(unique);
    Map<String, Integer> mapping = new HashMap<>();
    for (int i = 0; i < categories.size(); i++) mapping.put(categories.get(i), i);
    List<List<Integer>> result = new ArrayList<>();
    for (String label : labels) {
        Integer[] vec = new Integer[categories.size()];
        Arrays.fill(vec, 0);
        vec[mapping.get(label)] = 1;
        result.add(Arrays.asList(vec));
    }
    return result;
}

