import java.util.*;

public static String knnPredict(List<int[]> trainPoints, List<String> trainLabels, int[] testPoint, int k) {
    List<Pair> list = new ArrayList<>();
    for (int i = 0; i < trainPoints.size(); i++) {
        double dist = Math.hypot(trainPoints.get(i)[0] - testPoint[0], trainPoints.get(i)[1] - testPoint[1]);
        list.add(new Pair(dist, trainLabels.get(i)));
    }
    list.sort(Comparator.comparingDouble(p -> p.dist));
    Map<String, Integer> count = new HashMap<>();
    for (int i = 0; i < k; i++) count.put(list.get(i).label, count.getOrDefault(list.get(i).label, 0) + 1);
    return Collections.max(count.entrySet(), Map.Entry.comparingByValue()).getKey();
}
static class Pair { double dist; String label; Pair(double d, String l) { dist = d; label = l; } }

