function knnPredict(trainPoints, trainLabels, testPoint, k) {
    const distances = trainPoints.map((p, i) => ({
        dist: Math.hypot(p[0] - testPoint[0], p[1] - testPoint[1]),
        label: trainLabels[i]
    }));
    distances.sort((a,b) => a.dist - b.dist);
    const kNearest = distances.slice(0, k);
    const votes = {};
    for (let {label} of kNearest) votes[label] = (votes[label] || 0) + 1;
    return Object.keys(votes).reduce((a,b) => votes[a] > votes[b] ? a : b);
}

