def linear_regression_fit(X, y, lr=0.01, epochs=100):
    w, b = 0.0, 0.0
    n = len(X)
    for _ in range(epochs):
        pred = [w*x + b for x in X]
        dw = (2/n) * sum((pred[i] - y[i]) * X[i] for i in range(n))
        db = (2/n) * sum(pred[i] - y[i] for i in range(n))
        w -= lr * dw
        b -= lr * db
    return round(w, 2), round(b, 2)

