public static (double w, double b) LinearRegressionFit(double[] X, double[] y, double lr = 0.01, int epochs = 100) {
    double w = 0, b = 0;
    int n = X.Length;
    for (int epoch = 0; epoch < epochs; epoch++) {
        double dw = 0, db = 0;
        for (int i = 0; i < n; i++) {
            double pred = w * X[i] + b;
            double error = pred - y[i];
            dw += error * X[i];
            db += error;
        }
        dw = 2.0 / n * dw;
        db = 2.0 / n * db;
        w -= lr * dw;
        b -= lr * db;
    }
    return (Math.Round(w, 2), Math.Round(b, 2));
}

