using System;
using System.Collections.Generic;
using System.Linq;

public static List<int> KMeans(List<(double, double)> points, int k, int maxIters = 100) {
    var rand = new Random(42);
    var centroids = points.OrderBy(x => rand.Next()).Take(k).ToList();
    var assignments = new int[points.Count];
    for (int iter = 0; iter < maxIters; iter++) {
        var newAssignments = new int[points.Count];
        for (int i = 0; i < points.Count; i++) {
            var dists = centroids.Select((c, idx) => (idx, Math.Pow(points[i].Item1 - c.Item1, 2) + Math.Pow(points[i].Item2 - c.Item2, 2)));
            newAssignments[i] = dists.OrderBy(d => d.Item2).First().idx;
        }
        if (newAssignments.SequenceEqual(assignments)) break;
        assignments = newAssignments;
        var newCentroids = new List<(double, double)>();
        for (int i = 0; i < k; i++) {
            var cluster = points.Where((p, idx) => assignments[idx] == i).ToList();
            if (cluster.Any()) newCentroids.Add((cluster.Average(p => p.Item1), cluster.Average(p => p.Item2)));
            else newCentroids.Add(points[rand.Next(points.Count)]);
        }
        centroids = newCentroids;
    }
    return assignments.ToList();
}

