import java.util.*;

public static List<Integer> kmeans(List<double[]> points, int k, int maxIters) {
    Random rand = new Random(42);
    List<double[]> centroids = new ArrayList<>();
    Set<Integer> indices = new HashSet<>();
    while (centroids.size() < k) {
        int idx = rand.nextInt(points.size());
        if (!indices.contains(idx)) {
            indices.add(idx);
            centroids.add(points.get(idx));
        }
    }
    int[] assignments = new int[points.size()];
    for (int iter = 0; iter < maxIters; iter++) {
        int[] newAssignments = new int[points.size()];
        for (int i = 0; i < points.size(); i++) {
            double[] p = points.get(i);
            int bestIdx = 0;
            double bestDist = Double.MAX_VALUE;
            for (int j = 0; j < centroids.size(); j++) {
                double[] c = centroids.get(j);
                double dist = Math.hypot(p[0]-c[0], p[1]-c[1]);
                if (dist < bestDist) { bestDist = dist; bestIdx = j; }
            }
            newAssignments[i] = bestIdx;
        }
        if (Arrays.equals(newAssignments, assignments)) break;
        assignments = newAssignments;
        List<double[]> newCentroids = new ArrayList<>();
        for (int j = 0; j < k; j++) {
            List<double[]> cluster = new ArrayList<>();
            for (int i = 0; i < points.size(); i++) if (assignments[i] == j) cluster.add(points.get(i));
            if (!cluster.isEmpty()) {
                double sumX = 0, sumY = 0;
                for (double[] p : cluster) { sumX += p[0]; sumY += p[1]; }
                newCentroids.add(new double[]{sumX/cluster.size(), sumY/cluster.size()});
            } else newCentroids.add(points.get(rand.nextInt(points.size())));
        }
        centroids = newCentroids;
    }
    List<Integer> result = new ArrayList<>();
    for (int a : assignments) result.add(a);
    return result;
}

