function kmeans(points, k, maxIters = 100) {
    const seed = 42;
    function randomSample(arr, k) {
        const shuffled = [...arr];
        for (let i = shuffled.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
        }
        return shuffled.slice(0, k);
    }
    let centroids = randomSample(points, k);
    let assignments = new Array(points.length).fill(0);
    for (let iter = 0; iter < maxIters; iter++) {
        const newAssignments = points.map(p => {
            let minDist = Infinity, bestIdx = 0;
            centroids.forEach((c, idx) => {
                const dist = Math.hypot(p[0]-c[0], p[1]-c[1]);
                if (dist < minDist) { minDist = dist; bestIdx = idx; }
            });
            return bestIdx;
        });
        if (newAssignments.every((v,i) => v === assignments[i])) break;
        assignments = newAssignments;
        const newCentroids = [];
        for (let i = 0; i < k; i++) {
            const cluster = points.filter((_, idx) => assignments[idx] === i);
            if (cluster.length) {
                const meanX = cluster.reduce((s,p) => s + p[0], 0) / cluster.length;
                const meanY = cluster.reduce((s,p) => s + p[1], 0) / cluster.length;
                newCentroids.push([meanX, meanY]);
            } else newCentroids.push(points[Math.floor(Math.random() * points.length)]);
        }
        centroids = newCentroids;
    }
    return assignments;
}

