public static double[] Softmax(double[] z) {
    var exp = z.Select(v => Math.Exp(v)).ToArray();
    double sum = exp.Sum();
    return exp.Select(v => v / sum).ToArray();
}

public static double[] Relu(double[] z) => z.Select(v => Math.Max(0, v)).ToArray();

public static double[] Forward(double[] x, double[][] W1, double[] b1, double[][] W2, double[] b2) {
    int hiddenSize = b1.Length;
    double[] z1 = new double[hiddenSize];
    for (int i = 0; i < hiddenSize; i++) {
        z1[i] = b1[i];
        for (int j = 0; j < x.Length; j++) z1[i] += W1[i][j] * x[j];
    }
    double[] h = Relu(z1);
    int outputSize = b2.Length;
    double[] z2 = new double[outputSize];
    for (int i = 0; i < outputSize; i++) {
        z2[i] = b2[i];
        for (int j = 0; j < h.Length; j++) z2[i] += W2[i][j] * h[j];
    }
    return Softmax(z2);
}

