}

function relu(z) {
    return z.map(v => Math.max(0, v));
}

function forward(x, W1, b1, W2, b2) {
    // hidden
    const z1 = b1.map((b, i) => b + W1[i].reduce((sum, w, j) => sum + w * x[j], 0));
    const h = relu(z1);
    // output
    const z2 = b2.map((b, i) => b + W2[i].reduce((sum, w, j) => sum + w * h[j], 0));
    return softmax(z2);
}

