using System;
using System.Collections.Generic;
using System.Linq;

public static List<(List<int> train, List<int> test)> KFoldSplit<T>(List<T> data, int k, int seed = 42) {
    var rng = new Random(seed);
    var indices = Enumerable.Range(0, data.Count).ToList();
    indices = indices.OrderBy(i => rng.Next()).ToList();
    var folds = new List<(List<int>, List<int>)>();
    int foldSize = data.Count / k;
    int remainder = data.Count % k;
    int start = 0;
    for (int i = 0; i < k; i++) {
        int extra = i < remainder ? 1 : 0;
        int end = start + foldSize + extra;
        var testIdx = indices.GetRange(start, end - start);
        var trainIdx = indices.Take(start).Concat(indices.Skip(end)).ToList();
        folds.Add((trainIdx, testIdx));
        start = end;
    }
    return folds;
}

