import java.util.*;
import java.util.stream.Collectors;

public static List<Pair<List<Integer>, List<Integer>>> kfoldSplit(List<?> data, int k, int seed) {
    Random rng = new Random(seed);
    List<Integer> indices = new ArrayList<>();
    for (int i = 0; i < data.size(); i++) indices.add(i);
    Collections.shuffle(indices, rng);
    List<Pair<List<Integer>, List<Integer>>> folds = new ArrayList<>();
    int foldSize = data.size() / k;
    int remainder = data.size() % k;
    int start = 0;
    for (int i = 0; i < k; i++) {
        int extra = i < remainder ? 1 : 0;
        int end = start + foldSize + extra;
        List<Integer> testIdx = indices.subList(start, end);
        List<Integer> trainIdx = new ArrayList<>();
        trainIdx.addAll(indices.subList(0, start));
        trainIdx.addAll(indices.subList(end, indices.size()));
        folds.add(new Pair<>(trainIdx, testIdx));
        start = end;
    }
    return folds;
}
static class Pair<A,B> { public A first; public B second; Pair(A a,B b) { first=a; second=b; } }

