function kfoldSplit(data, k, seed = 42) {
    function seededRandom(seed) {
        let m = 0x80000000;
        let a = 1103515245;
        let c = 12345;
        return function() {
            seed = (a * seed + c) % m;
            return seed / m;
        };
    }
    const rng = seededRandom(seed);
    let indices = data.map((_, i) => i);
    for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(rng() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
    }
    const folds = [];
    const foldSize = Math.floor(data.length / k);
    const remainder = data.length % k;
    let start = 0;
    for (let i = 0; i < k; i++) {
        const extra = i < remainder ? 1 : 0;
        const end = start + foldSize + extra;
        const testIdx = indices.slice(start, end);
        const trainIdx = [...indices.slice(0, start), ...indices.slice(end)];
        folds.push({ train: trainIdx, test: testIdx });
        start = end;
    }
    return folds;
}

