using System.Collections.Generic;
using System.Linq;

public static double GiniImpurity<T>(List<T> labels) {
    int total = labels.Count;
    if (total == 0) return 0;
    var counts = labels.GroupBy(x => x).ToDictionary(g => g.Key, g => g.Count());
    double sumSq = counts.Values.Sum(c => Math.Pow((double)c / total, 2));
    return Math.Round(1 - sumSq, 3);
}

