import java.util.*;

public static double giniImpurity(List<String> labels) {
    int total = labels.size();
    if (total == 0) return 0;
    Map<String, Integer> counts = new HashMap<>();
    for (String l : labels) counts.put(l, counts.getOrDefault(l, 0) + 1);
    double sumSq = 0;
    for (int c : counts.values()) sumSq += Math.pow((double)c / total, 2);
    return Math.round((1 - sumSq) * 1000) / 1000.0;
}

