def perceptron_fit(X, y, epochs=10, lr=0.1):
    n_features = len(X[0])
    w = [0.0]*n_features
    b = 0.0
    for _ in range(epochs):
        for xi, yi in zip(X, y):
            pred = 1 if sum(w[j]*xi[j] for j in range(n_features)) + b > 0 else 0
            error = yi - pred
            if error != 0:
                for j in range(n_features):
                    w[j] += lr * error * xi[j]
                b += lr * error
    return w, b

