using System;
using System.Collections.Generic;
using System.Linq;

public static List<int> KMedoids(List<(int,int)> points, int k, int maxIters = 100, int seed = 42) {
    var rand = new Random(seed);
    int n = points.Count;
    var medoids = Enumerable.Range(0, n).OrderBy(x => rand.Next()).Take(k).ToList();
    var assignments = new int[n];
    for (int iter = 0; iter < maxIters; iter++) {
        var newAssign = new int[n];
        for (int i = 0; i < n; i++) {
            var dists = medoids.Select(m => Math.Abs(points[i].Item1 - points[m].Item1) + Math.Abs(points[i].Item2 - points[m].Item2)).ToList();
            newAssign[i] = dists.IndexOf(dists.Min());
        }
        if (newAssign.SequenceEqual(assignments)) break;
        assignments = newAssign;
        var newMedoids = new List<int>();
        for (int c = 0; c < k; c++) {
            var clusterIdx = Enumerable.Range(0, n).Where(i => assignments[i] == c).ToList();
            if (!clusterIdx.Any()) { newMedoids.Add(rand.Next(n)); continue; }
            int bestM = clusterIdx[0];
            double bestCost = double.MaxValue;
            foreach (int cand in clusterIdx) {
                double cost = clusterIdx.Sum(j => Math.Abs(points[cand].Item1 - points[j].Item1) + Math.Abs(points[cand].Item2 - points[j].Item2));
                if (cost < bestCost) { bestCost = cost; bestM = cand; }
            }
            newMedoids.Add(bestM);
        }
        medoids = newMedoids;
    }
    return assignments.ToList();
}

