import java.util.*;

public static List<Integer> kmedoids(List<int[]> points, int k, int maxIters, int seed) {
    Random rand = new Random(seed);
    int n = points.size();
    List<Integer> indices = new ArrayList<>();
    for (int i = 0; i < n; i++) indices.add(i);
    Collections.shuffle(indices, rand);
    List<Integer> medoids = new ArrayList<>(indices.subList(0, k));
    int[] assignments = new int[n];
    for (int iter = 0; iter < maxIters; iter++) {
        int[] newAssign = new int[n];
        for (int i = 0; i < n; i++) {
            int[] p = points.get(i);
            int bestDist = Integer.MAX_VALUE;
            int bestIdx = 0;
            for (int m = 0; m < medoids.size(); m++) {
                int[] med = points.get(medoids.get(m));
                int dist = Math.abs(p[0]-med[0]) + Math.abs(p[1]-med[1]);
                if (dist < bestDist) { bestDist = dist; bestIdx = m; }
            }
            newAssign[i] = bestIdx;
        }
        if (Arrays.equals(newAssign, assignments)) break;
        assignments = newAssign;
        List<Integer> newMedoids = new ArrayList<>();
        for (int c = 0; c < k; c++) {
            List<Integer> cluster = new ArrayList<>();
            for (int i = 0; i < n; i++) if (assignments[i] == c) cluster.add(i);
            if (cluster.isEmpty()) { newMedoids.add(rand.nextInt(n)); continue; }
            int bestM = cluster.get(0);
            double bestCost = Double.MAX_VALUE;
            for (int cand : cluster) {
