function kmedoids(points, k, maxIters = 100, seed = 42) {
    function seededRandom(seed) {
        let m = 0x80000000;
        let a = 1103515245;
        let c = 12345;
        return function() {
            seed = (a * seed + c) % m;
            return seed / m;
        };
    }
    const rng = seededRandom(seed);
    const n = points.length;
    let indices = [...Array(n).keys()];
    for (let i = n - 1; i > 0; i--) {
        const j = Math.floor(rng() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
    }
    let medoids = indices.slice(0, k);
    let assignments = new Array(n).fill(0);
    for (let iter = 0; iter < maxIters; iter++) {
        const newAssign = [];
        for (let i = 0; i < n; i++) {
            const p = points[i];
            let bestDist = Infinity, bestIdx = 0;
            for (let m = 0; m < medoids.length; m++) {
                const med = points[medoids[m]];
                const dist = Math.abs(p[0]-med[0]) + Math.abs(p[1]-med[1]);
                if (dist < bestDist) { bestDist = dist; bestIdx = m; }
            }
            newAssign.push(bestIdx);
        }
        if (newAssign.every((v,i) => v === assignments[i])) break;
        assignments = newAssign;
        const newMedoids = [];
        for (let c = 0; c < k; c++) {
            const cluster = [];
            for (let i = 0; i < n; i++) if (assignments[i] === c) cluster.push(i);
            if (cluster.length === 0) { newMedoids.push(Math.floor(rng() * n)); continue; }
            let bestM = cluster[0];
            let bestCost = Infinity;
            for (let cand of cluster) {
                let cost = 0;
                for (let j of cluster) {
                    cost += Math.abs(points[cand][0]-points[j][0]) + Math.abs(points[cand][1]-points[j][1]);
                }
                if (cost < bestCost) { bestCost = cost; bestM = cand; }
            }
            newMedoids.push(bestM);
        }
        medoids = newMedoids;
    }
    return assignments;
}

