using System;
using System.Linq;

public static (double threshold, int polarity, double error) BestStump(double[] X, int[] y, double[] weights) {
    var data = X.Zip(y, (x, yv) => (x, yv)).Zip(weights, (t, w) => (t.x, t.yv, w)).OrderBy(d => d.x).ToList();
    double totalPos = data.Where(d => d.yv == 1).Sum(d => d.w);
    double totalNeg = data.Where(d => d.yv == -1).Sum(d => d.w);
    double leftPos = 0, leftNeg = 0;
    double bestError = double.MaxValue;
    double bestThresh = 0;
    int bestPolarity = 1;
    for (int i = 0; i < data.Count - 1; i++) {
        var (x, yv, w) = data[i];
        if (yv == 1) leftPos += w; else leftNeg += w;
        double thresh = (x + data[i+1].x) / 2;
        double errorPlus = leftNeg + (totalPos - leftPos);
        double errorMinus = leftPos + (totalNeg - leftNeg);
        if (errorPlus < bestError) { bestError = errorPlus; bestThresh = thresh; bestPolarity = 1; }
        if (errorMinus < bestError) { bestError = errorMinus; bestThresh = thresh; bestPolarity = -1; }
    }
    return (bestThresh, bestPolarity, bestError);
}

