using System;
using System.Collections.Generic;
using System.Linq;

public static List<double> Pca(List<double[]> X, int nComponents = 1) {
    int n = X.Count;
    int dim = X[0].Length;
    double[] mean = new double[dim];
    for (int j = 0; j < dim; j++) mean[j] = X.Average(p => p[j]);
    var centered = X.Select(p => p.Select((v, j) => v - mean[j]).ToArray()).ToList();
    double[,] cov = new double[dim, dim];
    for (int i = 0; i < dim; i++) {
        for (int j = 0; j < dim; j++) {
            cov[i, j] = centered.Sum(p => p[i] * p[j]) / (n - 1);
        }
    }
    // 2D case
    double a = cov[0,0], b = cov[0,1], c = cov[1,1];
    double trace = a + c;
    double det = a * c - b * b;
    double lambda1 = (trace + Math.Sqrt(trace * trace - 4 * det)) / 2;
    double[] v;
    if (Math.Abs(b) > 1e-9) v = new double[] { lambda1 - c, b };
    else v = a >= c ? new double[] { 1, 0 } : new double[] { 0, 1 };
    double norm = Math.Sqrt(v[0]*v[0] + v[1]*v[1]);
    v[0] /= norm; v[1] /= norm;
    return centered.Select(p => p[0]*v[0] + p[1]*v[1]).ToList();
}

