import java.util.*;

public static List<Double> pca(List<double[]> X, int nComponents) {
    int n = X.size();
    int dim = X.get(0).length;
    double[] mean = new double[dim];
    for (double[] p : X) for (int j = 0; j < dim; j++) mean[j] += p[j];
    for (int j = 0; j < dim; j++) mean[j] /= n;
    List<double[]> centered = new ArrayList<>();
    for (double[] p : X) {
        double[] c = new double[dim];
        for (int j = 0; j < dim; j++) c[j] = p[j] - mean[j];
        centered.add(c);
    }
    double[][] cov = new double[dim][dim];
    for (int i = 0; i < dim; i++) {
        for (int j = 0; j < dim; j++) {
            double sum = 0;
            for (double[] c : centered) sum += c[i] * c[j];
            cov[i][j] = sum / (n - 1);
        }
    }
    double a = cov[0][0], b = cov[0][1], c = cov[1][1];
    double trace = a + c;
    double det = a * c - b * b;
    double lambda1 = (trace + Math.sqrt(trace * trace - 4 * det)) / 2;
    double[] v;
    if (Math.abs(b) > 1e-9) v = new double[]{lambda1 - c, b};
    else v = a >= c ? new double[]{1, 0} : new double[]{0, 1};
    double norm = Math.sqrt(v[0]*v[0] + v[1]*v[1]);
    v[0] /= norm; v[1] /= norm;
    List<Double> transformed = new ArrayList<>();
    for (double[] c : centered) transformed.add(c[0]*v[0] + c[1]*v[1]);
    return transformed;
}

