from collections import Counter
import math

class NaiveBayes:
    def fit(self, X, y):
        self.classes = set(y)
        self.class_priors = {c: y.count(c)/len(y) for c in self.classes}
        self.word_counts = {c: Counter() for c in self.classes}
        self.total_words = {c: 0 for c in self.classes}
        for doc, label in zip(X, y):
            for word in doc:
                self.word_counts[label][word] += 1
                self.total_words[label] += 1
        self.vocab = set(word for doc in X for word in doc)
        self.alpha = 1
    def predict(self, X):
        preds = []
        for doc in X:
            scores = {}
            for c in self.classes:
                log_prob = math.log(self.class_priors[c])
                for word in doc:
                    count = self.word_counts[c].get(word, 0)
                    prob = (count + self.alpha) / (self.total_words[c] + self.alpha * len(self.vocab))
                    log_prob += math.log(prob)
                scores[c] = log_prob
            preds.append(max(scores, key=scores.get))
        return preds

