    private Dictionary<int, double> classPriors;
    private Dictionary<int, Dictionary<string, int>> wordCounts;
    private Dictionary<int, int> totalWords;
    private HashSet<string> vocab;
    private int alpha = 1;

    public void Fit(List<string[]> X, int[] y) {
        classes = new HashSet<int>(y);
        classPriors = new Dictionary<int, double>();
        wordCounts = new Dictionary<int, Dictionary<string, int>>();
        totalWords = new Dictionary<int, int>();
        vocab = new HashSet<string>();
        foreach (var c in classes) { wordCounts[c] = new Dictionary<string, int>(); totalWords[c] = 0; }
        int n = X.Count;
        foreach (var c in classes) classPriors[c] = y.Count(l => l == c) / (double)n;
        for (int i = 0; i < n; i++) {
            var doc = X[i];
            int label = y[i];
            foreach (var word in doc) {
                vocab.Add(word);
                if (!wordCounts[label].ContainsKey(word)) wordCounts[label][word] = 0;
                wordCounts[label][word]++;
                totalWords[label]++;
            }
        }
    }

    public int[] Predict(List<string[]> X) {
        var results = new List<int>();
        foreach (var doc in X) {
            double bestScore = double.NegativeInfinity;
            int bestClass = 0;
            foreach (var c in classes) {
                double logProb = Math.Log(classPriors[c]);
                foreach (var word in doc) {
                    int count = wordCounts[c].ContainsKey(word) ? wordCounts[c][word] : 0;
                    double prob = (count + alpha) / (double)(totalWords[c] + alpha * vocab.Count);
                    logProb += Math.Log(prob);
                }
                if (logProb > bestScore) { bestScore = logProb; bestClass = c; }
            }
            results.Add(bestClass);
