import java.util.*;

public class NaiveBayes {
    private Set<Integer> classes;
    private Map<Integer, Double> classPriors;
    private Map<Integer, Map<String, Integer>> wordCounts;
    private Map<Integer, Integer> totalWords;
    private Set<String> vocab;
    private int alpha = 1;

    public void fit(List<String[]> X, int[] y) {
        classes = new HashSet<>();
        for (int label : y) classes.add(label);
        classPriors = new HashMap<>();
        wordCounts = new HashMap<>();
        totalWords = new HashMap<>();
        vocab = new HashSet<>();
        for (int c : classes) { wordCounts.put(c, new HashMap<>()); totalWords.put(c, 0); }
        int n = X.size();
        for (int c : classes) {
            int count = 0;
            for (int label : y) if (label == c) count++;
            classPriors.put(c, count / (double) n);
        }
        for (int i = 0; i < n; i++) {
            String[] doc = X.get(i);
            int label = y[i];
            for (String word : doc) {
                vocab.add(word);
                Map<String, Integer> map = wordCounts.get(label);
                map.put(word, map.getOrDefault(word, 0) + 1);
                totalWords.put(label, totalWords.get(label) + 1);
            }
        }
    }

    public int[] predict(List<String[]> X) {
        List<Integer> results = new ArrayList<>();
        for (String[] doc : X) {
            double bestScore = Double.NEGATIVE_INFINITY;
            int bestClass = 0;
            for (int c : classes) {
                double logProb = Math.log(classPriors.get(c));
                for (String word : doc) {
                    int count = wordCounts.get(c).getOrDefault(word, 0);
                    double prob = (count + alpha) / (double)(totalWords.get(c) + alpha * vocab.size());
                    logProb += Math.log(prob);
                }
                if (logProb > bestScore) { bestScore = logProb; bestClass = c; }
            }
            results.add(bestClass);
        }
        return results.stream().mapToInt(i->i).toArray();
    }
}

