public static Dictionary<string, object> DecodeJwtPayload(string token) {
    var parts = token.Split('.');
    if (parts.Length != 3) return null;
    string payloadB64 = parts[1];
    // replace URL-safe chars
    payloadB64 = payloadB64.Replace('-', '+').Replace('_', '/');
    switch (payloadB64.Length % 4) {
        case 2: payloadB64 += "=="; break;
        case 3: payloadB64 += "="; break;
    }
    byte[] bytes = Convert.FromBase64String(payloadB64);
    string json = Encoding.UTF8.GetString(bytes);
    return JsonSerializer.Deserialize<Dictionary<string, object>>(json);
}

