public class RateLimiter {
    private Dictionary<string, Queue<DateTime>> _store = new();
    public bool RateLimit(string ip, (int maxRequests, int windowSeconds) limits) {
        if (!_store.ContainsKey(ip)) _store[ip] = new Queue<DateTime>();
        var q = _store[ip];
        var now = DateTime.UtcNow;
        while (q.Count > 0 && (now - q.Peek()).TotalSeconds > limits.windowSeconds) q.Dequeue();
