import java.util.*;

public class RateLimiter {
    private Map<String, Queue<Long>> store = new HashMap<>();
    public boolean rateLimit(String ip, int maxRequests, int windowSeconds) {
        Queue<Long> q = store.getOrDefault(ip, new LinkedList<>());
        long now = System.currentTimeMillis() / 1000;
        while (!q.isEmpty() && q.peek() < now - windowSeconds) q.poll();
        if (q.size() >= maxRequests) return false;
        q.offer(now);
        store.put(ip, q);
        return true;
    }
}

