using System;
using System.Timers;

public static Action<T> Debounce<T>(Action<T> action, int delay) {
    Timer timer = null;
    return (arg) => {
        timer?.Stop();
        timer = new Timer(delay);
        timer.Elapsed += (sender, e) => {
            timer.Stop();
            action(arg);
        };
        timer.Start();
    };
}

