using System;
using System.Collections.Generic;
using System.Linq;

public static List<(int,int)> AStar(int[][] grid, (int,int) start, (int,int) goal) {
    int rows = grid.Length, cols = grid[0].Length;
    var openSet = new SortedSet<(int f, int g, (int,int) pos)>(Comparer<(int, int, (int,int))>.Create((a,b) => a.f != b.f ? a.f.CompareTo(b.f) : (a.g != b.g ? a.g.CompareTo(b.g) : 0)));
    var gScore = new Dictionary<(int,int), int> { [start] = 0 };
    var fScore = new Dictionary<(int,int), int> { [start] = Math.Abs(start.Item1-goal.Item1) + Math.Abs(start.Item2-goal.Item2) };
    var cameFrom = new Dictionary<(int,int), (int,int)>();
    openSet.Add((fScore[start], gScore[start], start));
    while (openSet.Count > 0) {
        var current = openSet.Min.pos;
        openSet.Remove(openSet.Min);
        if (current.Equals(goal)) {
            var path = new List<(int,int)>();
            while (cameFrom.ContainsKey(current)) { path.Add(current); current = cameFrom[current]; }
            path.Add(start); path.Reverse(); return path;
        }
        foreach (var (dx,dy) in new[] {(1,0),(-1,0),(0,1),(0,-1)}) {
            var neighbor = (current.Item1+dx, current.Item2+dy);
            if (neighbor.Item1 < 0 || neighbor.Item1 >= rows || neighbor.Item2 < 0 || neighbor.Item2 >= cols) continue;
            if (grid[neighbor.Item1][neighbor.Item2] == 1) continue;
            int tentativeG = gScore[current] + 1;
            if (tentativeG < gScore.GetValueOrDefault(neighbor, int.MaxValue)) {
                cameFrom[neighbor] = current;
                gScore[neighbor] = tentativeG;
                int f = tentativeG + Math.Abs(neighbor.Item1-goal.Item1) + Math.Abs(neighbor.Item2-goal.Item2);
                fScore[neighbor] = f;
                openSet.Add((f, tentativeG, neighbor));
            }
        }
    }
    return new List<(int,int)>();
}

