import java.util.*;

public static List<int[]> aStar(int[][] grid, int[] start, int[] goal) {
    int rows = grid.length, cols = grid[0].length;
    PriorityQueue<int[]> openSet = new PriorityQueue<>(Comparator.comparingInt(a -> a[2]));
    Map<String, Integer> gScore = new HashMap<>();
    Map<String, Integer> fScore = new HashMap<>();
    Map<String, String> cameFrom = new HashMap<>();
    String startKey = start[0]+","+start[1];
    gScore.put(startKey, 0);
    fScore.put(startKey, Math.abs(start[0]-goal[0])+Math.abs(start[1]-goal[1]));
    openSet.offer(new int[]{start[0], start[1], fScore.get(startKey)});
    while (!openSet.isEmpty()) {
        int[] curr = openSet.poll();
        int x=curr[0], y=curr[1];
        if (x==goal[0] && y==goal[1]) {
            List<int[]> path = new ArrayList<>();
            String key = x+","+y;
            while (cameFrom.containsKey(key)) {
                String[] parts = key.split(",");
                path.add(new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1])});
                key = cameFrom.get(key);
            }
            path.add(start);
            Collections.reverse(path);
            return path;
        }
        for (int[] dir : new int[][]{{1,0},{-1,0},{0,1},{0,-1}}) {
            int nx = x+dir[0], ny = y+dir[1];
            if (nx<0 || nx>=rows || ny<0 || ny>=cols) continue;
            if (grid[nx][ny]==1) continue;
            int tentativeG = gScore.getOrDefault(x+","+y, Integer.MAX_VALUE) + 1;
            String neighborKey = nx+","+ny;
            if (tentativeG < gScore.getOrDefault(neighborKey, Integer.MAX_VALUE)) {
                cameFrom.put(neighborKey, x+","+y);
                gScore.put(neighborKey, tentativeG);
                int f = tentativeG + Math.abs(nx-goal[0])+Math.abs(ny-goal[1]);
                fScore.put(neighborKey, f);
                openSet.offer(new int[]{nx, ny, f});
            }
        }
    }
    return new ArrayList<>();
}

