function aStar(grid, start, goal) {
    const rows = grid.length, cols = grid[0].length;
    const heuristic = (a,b) => Math.abs(a[0]-b[0]) + Math.abs(a[1]-b[1]);
    const openSet = new PriorityQueue((a,b) => a.f - b.f);
    const gScore = new Map();
    const fScore = new Map();
    const cameFrom = new Map();
    const startKey = start[0]+','+start[1];
    gScore.set(startKey, 0);
    fScore.set(startKey, heuristic(start, goal));
    openSet.enqueue({pos: start, f: fScore.get(startKey)});
    while (!openSet.isEmpty()) {
        const current = openSet.dequeue().pos;
        const [x,y] = current;
        if (x===goal[0] && y===goal[1]) {
            const path = [];
            let key = x+','+y;
            while (cameFrom.has(key)) {
                const [px,py] = cameFrom.get(key).split(',').map(Number);
                path.push([px,py]);
                key = cameFrom.get(key);
            }
            path.reverse();
            path.unshift(start);
            return path;
        }
        for (const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]) {
            const nx = x+dx, ny = y+dy;
            if (nx<0 || nx>=rows || ny<0 || ny>=cols) continue;
            if (grid[nx][ny] === 1) continue;
            const tentativeG = gScore.get(x+','+y) + 1;
            const neighborKey = nx+','+ny;
