// simple priority queue implementation
class PriorityQueue {
    constructor(compare) { this.heap = []; this.compare = compare; }
    enqueue(val) { this.heap.push(val); this._bubbleUp(this.heap.length-1); }
    dequeue() { const min = this.heap[0]; const last = this.heap.pop(); if (this.heap.length) { this.heap[0] = last; this._sinkDown(0); } return min; }
    isEmpty() { return this.heap.length === 0; }
    _bubbleUp(i) { while (i>0) { const p = (i-1)>>1; if (this.compare(this.heap[p], this.heap[i]) <= 0) break; [this.heap[p], this.heap[i]] = [this.heap[i], this.heap[p]]; i=p; } }
    _sinkDown(i) { const n=this.heap.length; while(true) { let left=2*i+1, right=2*i+2, swap=null; if (left<n && this.compare(this.heap[left], this.heap[i])<0) swap=left; if (right<n && this.compare(this.heap[right], this.heap[swap===null?i:left])<0) swap=right; if (swap===null) break; [this.heap[i], this.heap[swap]] = [this.heap[swap], this.heap[i]]; i=swap; } }
}

