    def __init__(self, x, y, w, h, capacity=4):
        self.bounds = (x, y, w, h)
        self.capacity = capacity
        self.points = []
        self.divided = False
    def subdivide(self):
        x,y,w,h = self.bounds
        hw, hh = w/2, h/2
        self.nw = QuadTree(x, y, hw, hh, self.capacity)
        self.ne = QuadTree(x+hw, y, hw, hh, self.capacity)
        self.sw = QuadTree(x, y+hh, hw, hh, self.capacity)
        self.se = QuadTree(x+hw, y+hh, hw, hh, self.capacity)
        self.divided = True
    def insert(self, x, y):
        if not (self.bounds[0] <= x < self.bounds[0]+self.bounds[2] and self.bounds[1] <= y < self.bounds[1]+self.bounds[3]):
            return False
        if len(self.points) < self.capacity and not self.divided:
            self.points.append((x,y))
            return True
        if not self.divided:
            self.subdivide()
            for (px,py) in self.points:
                self.nw.insert(px,py) or self.ne.insert(px,py) or self.sw.insert(px,py) or self.se.insert(px,py)
            self.points = []
        return (self.nw.insert(x,y) or self.ne.insert(x,y) or self.sw.insert(x,y) or self.se.insert(x,y))
    def query(self, rect):
        rx,ry,rw,rh = rect
        found = []
        if not self.intersects(rect):
            return found
        for (px,py) in self.points:
            if rx <= px < rx+rw and ry <= py < ry+rh:
