            found.extend(self.nw.query(rect))
            found.extend(self.ne.query(rect))
            found.extend(self.sw.query(rect))
            found.extend(self.se.query(rect))
        return found
    def intersects(self, rect):
        x,y,w,h = self.bounds
        rx,ry,rw,rh = rect
        return not (x+w < rx or x > rx+rw or y+h < ry or y > ry+rh)

