using System.Collections.Generic;

public class QuadTree {
    private (float x, float y, float w, float h) bounds;
    private int capacity;
    private List<(float,float)> points;
    private bool divided;
    private QuadTree nw, ne, sw, se;
    public QuadTree(float x, float y, float w, float h, int capacity = 4) {
        this.bounds = (x, y, w, h);
        this.capacity = capacity;
        this.points = new List<(float,float)>();
        this.divided = false;
    }
    private void Subdivide() {
        float x = bounds.x, y = bounds.y, w = bounds.w, h = bounds.h;
        float hw = w/2, hh = h/2;
        nw = new QuadTree(x, y, hw, hh, capacity);
        ne = new QuadTree(x+hw, y, hw, hh, capacity);
        sw = new QuadTree(x, y+hh, hw, hh, capacity);
        se = new QuadTree(x+hw, y+hh, hw, hh, capacity);
        divided = true;
    }
    public bool Insert(float x, float y) {
        if (!(bounds.x <= x && x < bounds.x+bounds.w && bounds.y <= y && y < bounds.y+bounds.h))
            return false;
        if (points.Count < capacity && !divided) {
            points.Add((x,y));
            return true;
        }
        if (!divided) Subdivide();
        if (nw.Insert(x,y)) return true;
        if (ne.Insert(x,y)) return true;
        if (sw.Insert(x,y)) return true;
        if (se.Insert(x,y)) return true;
        return false;
    }
    public List<(float,float)> Query((float x, float y, float w, float h) rect) {
        var found = new List<(float,float)>();
        if (!Intersects(rect)) return found;
        foreach (var p in points) {
            if (rect.x <= p.Item1 && p.Item1 < rect.x+rect.w && rect.y <= p.Item2 && p.Item2 < rect.y+rect.h)
                found.Add(p);
        }
        if (divided) {
            found.AddRange(nw.Query(rect));
            found.AddRange(ne.Query(rect));
            found.AddRange(sw.Query(rect));
            found.AddRange(se.Query(rect));
        }
        return found;
    }
    private bool Intersects((float x, float y, float w, float h) rect) {
        return !(bounds.x+bounds.w < rect.x || bounds.x > rect.x+rect.w || bounds.y+bounds.h < rect.y || bounds.y > rect.y+rect.h);
    }
}

