    private Random rng;
    private bool active;
    private float intensity, duration, remaining;
    public CameraShake(int seed = 42) { rng = new Random(seed); }
    public void Start(float intensity, float duration) {
        active = true;
        this.intensity = intensity;
        this.duration = duration;
        this.remaining = duration;
    }
    public (float dx, float dy) Update(float dt) {
        if (!active) return (0,0);
        remaining -= dt;
        if (remaining <= 0) { active = false; return (0,0); }
        float factor = remaining / duration;
        float maxOffset = intensity * factor;
        float dx = (float)(rng.NextDouble() * 2 * maxOffset - maxOffset);
        float dy = (float)(rng.NextDouble() * 2 * maxOffset - maxOffset);
        return (dx, dy);
    }
}

