class CameraShake {
    constructor(seed = 42) {
        this.seed = seed;
        this.active = false;
        this.intensity = 0;
        this.duration = 0;
        this.remaining = 0;
        // simple seeded random
        this.rng = function() {
            seed = (seed * 1103515245 + 12345) & 0x7fffffff;
            return seed / 0x7fffffff;
        };
    }
    start(intensity, duration) {
        this.active = true;
        this.intensity = intensity;
        this.duration = duration;
        this.remaining = duration;
    }
    update(dt) {
        if (!this.active) return [0,0];
        this.remaining -= dt;
        if (this.remaining <= 0) { this.active = false; return [0,0]; }
        const factor = this.remaining / this.duration;
        const maxOffset = this.intensity * factor;
        const dx = (this.rng() * 2 - 1) * maxOffset;
        const dy = (this.rng() * 2 - 1) * maxOffset;
        return [dx, dy];
    }
}

