        self.frame_count = 0
        self.time_accum = 0.0
    def tick(self, dt):
        self.frame_count += 1
        self.time_accum += dt
        if self.time_accum >= 1.0:
            fps = self.frame_count / self.time_accum
            self.frame_count = 0
            self.time_accum = 0.0
            return round(fps)
        return None

