public class FPSCounter {
    private int frameCount = 0;
    private float timeAccum = 0f;
    public int? Tick(float dt) {
        frameCount++;
        timeAccum += dt;
        if (timeAccum >= 1.0f) {
            int fps = (int)Math.Round(frameCount / timeAccum);
            frameCount = 0;
            timeAccum = 0f;
            return fps;
        }
        return null;
    }
}

